// ── "BANNED" de la tienda ───────────────────────────────────────────────────
// Sustituye al precio en los botones vetados por el reto activo (hoy solo
// Comprar Gallina en Adán y Eva). Estaba hardcodeado en inglés en script.js,
// así que salía igual en los 16 idiomas — lo reportó un usuario italiano.
// Va en el hueco de un precio, así que conviene que sea corto.
(function () {
    var _bn = {
        en: "BANNED",      es: "BLOQUEADO",   'pt-br': "BLOQUEADO", it: "VIETATO",
        fr: "INTERDIT",    de: "GESPERRT",    ru: "ЗАПРЕЩЕНО",      tr: "YASAK",
        ja: "使用不可",     'zh-cn': "禁用",    ko: "사용 불가",        pl: "ZABLOKOWANE",
        sv: "SPÄRRAD",     nl: "GEBLOKKEERD", vi: "BỊ CẤM",         id: "DILARANG",
    };
    Object.keys(_bn).forEach(function (lang) {
        if (I18N[lang]) I18N[lang].shopBanned = _bn[lang];
    });
})();

window.P2P_FONT = ['ja', 'zh-cn'].includes(currentLang) ? 'DotGothic16' : (['ko', 'vi'].includes(currentLang) ? 'sans-serif' : 'Press Start 2P');
window.P2P_SCALE = (window.P2P_FONT === 'Press Start 2P') ? 1.0 : 1.35;
let targetFontInit = `"${window.P2P_FONT}", monospace, sans-serif`;
document.body.style.fontFamily = targetFontInit;
document.addEventListener('DOMContentLoaded', () => { window.changeLanguage(currentLang); });

window.t = function (key) {
    const val = (I18N[currentLang] && I18N[currentLang][key]) ? I18N[currentLang][key] : (I18N['en'][key] || key);
    if (Array.isArray(val)) return val[Math.floor(Math.random() * val.length)];
    return val;
}

window.applyTranslations = function () {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        el.innerHTML = window.t(key);
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        const translated = window.t(key);
        el.setAttribute('data-title', translated);
        const descDiv = el.querySelector('.shop-desc-text');
        if (descDiv) descDiv.innerHTML = translated;
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        el.setAttribute('placeholder', window.t(key));
    });
    // Prado mode names: strip "N. " number prefix from chal title keys
    document.querySelectorAll('[data-prado-name]').forEach(el => {
        const key = el.getAttribute('data-prado-name');
        el.textContent = window.t(key).replace(/^\d+\.\s*/, '');
    });
}

window.addEventListener('DOMContentLoaded', window.applyTranslations);
